<script setup lang="ts">
import { Head, router } from '@inertiajs/vue3'
import { reactive, ref } from 'vue'
import AuthenticatedLayout from '../../Layouts/AuthenticatedLayout.vue'
type Row = { id: number; internal_order_number: string; source_type: string; recipient_name: string | null; summary: { completeness: string; profit_status: string; net_revenue: string | null; total_cost: string | null; contribution_profit: string | null; margin: string | null }; values: Record<string, string | null> }
type Filters = { search?: string; source_type?: string; completeness?: string; profit_status?: string }
const props = defineProps<{ orders: Row[]; fields: string[]; filters: Filters }>()
const filters = reactive({ search: props.filters.search ?? '', source_type: props.filters.source_type ?? '', completeness: props.filters.completeness ?? '', profit_status: props.filters.profit_status ?? '' })
const editing = ref<number | null>(null)
const editValues = reactive<Record<string, string>>({})
const query = () => new URLSearchParams(Object.fromEntries(Object.entries(filters).filter(([, value]) => value)))
const submit = () => router.get('/accounting/order-costs', Object.fromEntries(query().entries()), { preserveState: true, replace: true })
const exportCsv = () => { window.location.href = `/accounting/order-costs/export?${query()}` }
const edit = (row: Row) => { editing.value = row.id; for (const field of props.fields) editValues[field] = row.values[field] ?? '' }
const save = (row: Row) => router.put(`/accounting/order-costs/${row.id}`, editValues, { onSuccess: () => { editing.value = null } })
</script>
<template>
  <Head title="订单分析 · BYL ERP" /><AuthenticatedLayout title="订单分析" :breadcrumbs="['BYL ERP', '会计', '每一单成本表']"><section class="mvp-page"><div class="mvp-page-heading"><div><p class="mvp-kicker">Finance / Order Analysis</p><h2>订单分析</h2><p>成本不完整时不显示 confirmed profit。</p></div><div class="mvp-form-actions page-header-actions"><button class="mvp-button" @click="exportCsv">导出 CSV</button></div></div><form class="mvp-toolbar" @submit.prevent="submit"><input v-model="filters.search" aria-label="搜索分析" placeholder="搜索订单、收件人或 SKU"><select v-model="filters.source_type" aria-label="来源"><option value="">全部来源</option><option value="website">website</option><option value="kol">kol</option><option value="manual_other">manual_other</option></select><select v-model="filters.completeness" aria-label="完整性"><option value="">全部完整性</option><option value="incomplete">不完整</option><option value="complete">完整</option></select><select v-model="filters.profit_status" aria-label="利润状态"><option value="">全部利润状态</option><option value="confirmed">已确认</option><option value="not_confirmed">未确认</option></select><button class="mvp-button" type="submit">筛选</button></form><div class="mvp-table-wrap"><table class="mvp-table"><thead><tr><th>订单号</th><th>来源</th><th>收件人</th><th>净收入</th><th>总成本</th><th>贡献利润</th><th>Margin</th><th>完整性</th><th>操作</th></tr></thead><tbody><template v-for="row in props.orders" :key="row.id"><tr><td>{{ row.internal_order_number }}</td><td>{{ row.source_type }}</td><td>{{ row.recipient_name }}</td><td>{{ row.summary.net_revenue ?? '—' }}</td><td>{{ row.summary.total_cost ?? '—' }}</td><td>{{ row.summary.contribution_profit ?? '未确认' }}</td><td>{{ row.summary.margin ?? '—' }}</td><td>{{ row.summary.completeness }}</td><td><button class="mvp-button" @click="edit(row)">{{ editing === row.id ? '编辑中' : '编辑成本' }}</button></td></tr><tr v-if="editing === row.id"><td colspan="9"><div class="mvp-form-grid"><label v-for="field in props.fields" :key="field">{{ field }}<input v-model="editValues[field]" inputmode="decimal"></label><button class="mvp-button mvp-button-primary" type="button" @click="save(row)">保存成本</button><button class="mvp-button" type="button" @click="editing = null">取消</button></div></td></tr></template><tr v-if="props.orders.length === 0"><td colspan="9" class="mvp-empty">暂无订单分析数据</td></tr></tbody></table></div></section></AuthenticatedLayout>
</template>
